test('이미지 변환은 실제 PNG/WebP의 해시·용량·크기와 경계를 검증하고 덮어쓰지 않는다',async t=>{
 const {default:fs}=await import('node:fs/promises');const {default:os}=await import('node:os');const {default:path}=await import('node:path');const {materializeAssets}=await import('./render-report-section.mjs');
 const root=await fs.mkdtemp(path.join(os.tmpdir(),'asset-test-'));t.after(()=>fs.rm(root,{recursive:true,force:true}));await fs.mkdir(path.join(root,'assets/report'),{recursive:true});await fs.mkdir(path.join(root,'_workspace'),{recursive:true});
 const src=Buffer.alloc(24);Buffer.from('89504e470d0a1a0a','hex').copy(src);src.write('IHDR',12);src.writeUInt32BE(1672,16);src.writeUInt32BE(941,20);const webp=Buffer.alloc(30);webp.write('RIFF');webp.writeUInt32LE(22,4);webp.write('WEBPVP8X',8);webp.writeUInt32LE(10,16);webp.writeUIntLE(1671,24,3);webp.writeUIntLE(940,27,3);await fs.writeFile(path.join(root,'assets/report/source.png'),src);await fs.writeFile(path.join(root,'_workspace/draft.webp'),webp);
 const h=b=>crypto.createHash('sha256').update(b).digest('hex');const review={reviewer:'reviewer',verdict:'pass',items:[{id:'source',verdict:'pass',sourceSha256:h(src),outputSha256:h(webp),width:1672,height:941}]};const evidence=Buffer.from(JSON.stringify(review));await fs.writeFile(path.join(root,'_workspace/quality.json'),evidence);
 const item={qualityReviewer:'reviewer',qualityEvidencePath:'_workspace/quality.json',qualityEvidenceSha256:h(evidence),sourcePath:'assets/report/source.png',sourceSha256:h(src),sourceBytes:src.length,draftPath:'_workspace/draft.webp',outputSha256:h(webp),outputBytes:webp.length,outputPath:'assets/report/output.webp',width:1672,height:941};
 for(const change of [{sourceSha256:'0'.repeat(64)},{qualityEvidenceSha256:'0'.repeat(64)},{outputBytes:1},{width:1},{draftPath:'_workspace/../assets/report/output.webp'}])await assert.rejects(materializeAssets(root,{assetDerivations:[{...item,...change}]}));
 for(const invalid of [{reviewed:true},{...review,reviewer:'other'},{...review,verdict:'fail'},{...review,items:[]},{...review,items:[review.items[0],review.items[0]]},{...review,items:[{...review.items[0],verdict:'fail'}]},{...review,items:[{...review.items[0],outputSha256:'0'.repeat(64)}]},{...review,items:[{...review.items[0],width:1}]}]){
  const bytes=Buffer.from(JSON.stringify(invalid));await fs.writeFile(path.join(root,'_workspace/quality.json'),bytes);await assert.rejects(materializeAssets(root,{assetDerivations:[{...item,qualityEvidenceSha256:h(bytes)}]}),/quality review/);
 }
 await fs.writeFile(path.join(root,'_workspace/quality.json'),evidence);
 assert.equal(await materializeAssets(root,{assetDerivations:[item]}),1);assert.deepEqual(await fs.readFile(path.join(root,item.outputPath)),webp);assert.equal(await materializeAssets(root,{assetDerivations:[item]}),1);
 await fs.writeFile(path.join(root,item.outputPath),'other');await assert.rejects(materializeAssets(root,{assetDerivations:[item]}),/differs/);assert.equal(await fs.readFile(path.join(root,item.outputPath),'utf8'),'other');
 await fs.symlink(path.join(root,'_workspace'),path.join(root,'assets/report/link'));await assert.rejects(materializeAssets(root,{assetDerivations:[{...item,outputPath:'assets/report/link/out.webp'}]}),/Symlink/);
});
